                    this.celkemStavUhradyKUhrade = 0;
                    this.celkemStavUhradyUhrazeno = 0;
                    this.celkemStavUhradyDluh = 0;
                    this.celkemPredpisyCastka = 0;
                    this.celkemPlatbyCastka = 0;
                    this.celkemVratkyCastka = 0;
                    this.celkemOprPolozkyCastka = 0;
                    this.celkemPohybyFUCCastka = 0;
                    this.celkemPoukazyCastka = 0;
                    this.celkemKontrolyCastka = 0;
                    this.celkemRozhodnutiCastka = 0;
                    this.celkemVymahaniCastka = 0;
                    //#endregion POROVNÁVAČ
                    //########################################################################################
                    this.inicializaceDetailu = true;
                    //#endregion Metoda pro automatizaci při testování
                    //#region I N I C I A L I Z A C E
                    this._initialized = false;
                    //#endregion 
