                //#region Metoda pro automatizaci při testování
                autoRunTestMethod() {
                    const that = this;
                    that.preplatekMenuOpen();
                    //that.prevodDluhu();
                    //that.zalozeniVratky();
                    //that.zmenaBankovnihoUctu();
                }
                initialize() {
                    if (this._initialized)
                        return;
                    if (this.DatSaldo == null)
                        this.DatSaldo = new Date(Date.now());
                    this.createLoadingPromise();
                    this._initialized = true;
                }
                createLoadingPromise() {
                    this.loadingPromise = $.Deferred();
                }
                /** Metoda pro znovu-načtení dat případu*/
                updateData() {
                    // Update dat a detailu 
                    const that = this;
                    that.taskPripad = that.isl.Pripad.read(rq => {
                        return {
                            data: { ixp: that.Ixp },
                            fragments: ["*", "ExterniSubjekt.Default", "Uroceni.*"]
                        };
                    }).get();
                    that.taskPripad.done((data) => {
                        const form = that.element.findForms();
                        that.model = data.data;
                        form.findFields()
                            .gfield("model", "apply", that.model, { initialValues: that.inicializaceDetailu })
                            .gfield("model", "validators", that.validators);
                        that.setKpis();
                        that.nastavStatusBar();
                        //that.nastavVarovani();
                        that.call("NacteniCelehoPopisuPripadu", { ixp: that.model.ixp })
                            .done(function (data) {
                            let popis = data ?? that.model.popis;
                            form.findFields("popis").gfield("setValue", popis, { initialValues: that.inicializaceDetailu });
                            that.endOperation();
                        });
                        that.endOperation();
                    });
                } //----updateData KONEC----
