                /** Metoda definující akce pro PLATBY na contentu a jejich registrace */
                createActionsPlatby() {
                    var that = this;
                    return ({
                        actGPripadPlatbyPodleVS: {
                            name: "actGPripadPlatbyPodleVS",
                            caption: "Platby dle VS",
                            tooltip: "Zobrazení plateb dle variabilního symbolu",
                            enabled: that.permsDto.buttons.pb_plat_dle_vs,
                            run: () => {
                                //let row = this.gridPlatby.find(".ggrid").ggrid<Ddp.Interface.LK.Isl.GPlatbyDto>("getSelection")
                                let row = this.gridPlatby.ggrid("activeRow");
                                if (row != null) {
                                    this.navigate("Gordic.Ddp.WebClient.GPlatbyVS", { ID: "DDPGPlatbyVS", VS: row.vs, TypPhl: that.TypPhl });
                                }
                            }
                        },
                        actGPripadUcZapPOK: {
                            name: "actGPripadUcZapPOK",
                            caption: "Uč. záp. POK",
                            tooltip: "Učetní zápis POK",
                            enabled: that.permsDto.buttons.pb_buc_uct_pok,
                            run: () => {
                                var filter = {};
                                let row = this.gridPlatby.ggrid("activeRow");
                                if (row != null) {
                                    if (row != null) {
                                        filter.ixp = row.ixp_pok;
                                        if (row.ixp_pok != null) {
                                            that.beginOperation({ id: "loadData" });
                                            that.isl.PlatbyVS.getKtgTyp(rq => {
                                                return {
                                                    filters: filter
                                                };
                                            }).get().done(function (dto) {
                                                var ktg_typ = dto.data[0].ktg_typ;
                                                that.endOperation({ id: "loadData" });
                                                if (ktg_typ != null)
                                                    Gordic.Eko.Dialogs.GVazby(that, { InputDto: { viewMode: true, ixp: row.ixp_pok, drd: 0, ktg_typ: parseInt(ktg_typ), lzePracovatSCizimiDoklady: false } });
                                            })
                                                .fail(function () {
                                                that.endOperation({ id: "loadData" });
                                            });
                                        }
                                        else {
                                            that.dialogs.error("Chyba", "Platba není realizována modulem POK!");
                                        }
                                    }
                                }
                            }
                        },
                        actGPripadVratit: {
                            name: "actGPripadVratit",
                            caption: "Vrátit",
                            tooltip: "Vrácení platby",
                            enabled: that.permsDto.buttons.pb_vratit_platbu,
                            run: () => {
                                var that = this;
                                if (that.params.ddp_rad_vratka != 1 && that.model.ixs_fun_akt != that.IxsFun) {
                                    return that.dialogs.error("Chyba", "Nejste zpracovatelem dokumentu!");
                                }
                                let row = that.gridPlatby.ggrid("activeRow");
                                if (row != null) {
                                    if (row.ixp_par?.length != 12 || row.ixp?.length != 12) {
                                        return that.dialogs.error("Chyba", "Vyberte prosím řádek platby, který chcete vracet!");
                                    }
                                    var ParamJSON = { ID: "DDPGDetailVratky#", Ixp: that.Ixp /* row.ixp */, Typ_phl: that.TypPhl, DtoPlatba: row, Edit: false, KurzyMenyDto: that.kurzyMenyDto, /*odesilatel: this.model.bu_vl*/ };
                                    that.navigate("Gordic.Ddp.WebClient.GDetailVratky", ParamJSON);
                                }
                                else {
                                    that.dialogs.warning("Upozornění", "Není vybrána platba k vrácení!");
                                }
                            }
                        },
                        actGPripadPlatbaParovani: {
                            name: "actGPripadPlatbaParovani",
                            caption: "Parování",
                            tooltip: "Parování plateb",
                            enabled: that.permsDto.buttons.pb_parovani,
                            run: () => {
                                const that = this;
                                let row = this.gridPlatby.ggrid("activeRow");
                                if (row != null) {
                                    //TODO: vytvořit funkci...
                                    that.dialogs.alert("Oznámení", "Tato akce zatím není implemenována.");
                                }
                            }
                        }
                    });
                }
