                                        inputDto: inputDto,
                                        init: (opts, filter) => {
                                            let esu = rows[0].ixs_esu;
                                            let smlouva = rows[0].ixp_sml;
                                            if (smlouva !== null) {
                                                filter.ixp_sml_pri = smlouva; // Když mám PID smlouvy, chci vyfiltrovat tu jednu smlouvu bez ohledu na cokoli
                                            }
                                            else {
                                                if (esu !== null)
                                                    filter.ixs_esu = esu; // Když smlouvy nemám zkusím filtrovat podle ESU
                                            }
                                        },
                                        //rowsEnabled: (meta) => meta.data.vyhovujici === true,
