                akce() {
                    const that = this;
                    var def = $.Deferred();
                    var msg = "";
                    that.dialogs.confirm("Upozornění", "Chcete použít splátkový kalendář?")
                        .on("close", (ev, retVal) => {
                        if (retVal === "yes") {
                            //that.dialogs.prompt("Zadej důvod zrušení příznaku tisku daňového dokladu")
                            //    .on("ok", function (ev, duvod) {
                            //        if (duvod && (duvod.trim() != "")) { // mám důvod
                            //            that.beginOperation({ id: "PripadPredpisyPriznakTiskuDDZrusit" });
                            //        }
                            //    }
                            if (that.model.ixp?.length != 12) {
                                return that.dialogs.error("Chyba", "Nelze přidávat do prázdného formuláře!");
                            }
                            if (that.model.ixs_fun_akt != that.IxsFun) {
                                msg = 'Nejste zpracovatelem dokumentu!';
                                return def.reject(msg);
                                // Call gf_ZobrazChybu('Nejste zpracovatelem dokumentu!')
                            }
                            //if (that.model.c_mena.is 0) // If df_c_mena = 0
                            //    //Call gf_ZobrazChybu('Není zadána částka!')
                            //    return;
                            //      If NOT Msg._question('Opravdu chcete přepočítat předpisy?')
                            //       Return 0
                            //      If SalModalDialog(dlg_get_year, hWndForm, pRok)
                            //       Call SalWaitCursor(1)
                            //       Call gf_ZobrazInformacniOkno('Probíhá přepočet předpisů...')
                            //       Call mdi_ddp.ddp_work._init()
                            //       If NOT mdi_ddp.ddp_work.chprep(df_ixp, pRok, 0)
                            //        Call SalWaitCursor(0)
                            //        Call Error._rollbackNoInfo()
                            //!Return 0
                            //       Call tbl_predpisy.Refresh()
                            //       Call gf_ZrusInformacniOkno()
                            //       Call SalWaitCursor(0)
                            def.reject(msg);
                        }
                        else {
                            def.resolve(msg);
                            //Set tbl_predpisy.nRow = -1
                            //Call tbl_predpisy.PrepocetPredpisu()
                            //Set tbl_predpisy.prepocteno = TRUE
                        }
                    });
                    return def.promise();
                }
