                                //var rows = this.gridPredpisy.ggrid<Ddp.Interface.LK.Isl.GPredpisDto>("getSelection");
                                var row = this.gridVratky.ggrid("getSelection")[0];
                                var rows = []; // = new Ddp.Interface.LK.Isl.GPredpisDto[];
