                /** Metoda definující akce pro Správu případů na contentu a jejich registrace */
                createActionsSpravaPrip() {
                    const that = this;
                    return ({
                        actGSprPred: {
                            name: "actGSprPred",
                            caption: "Předání správci",
                            tooltip: "Předat případ jinému správci",
                            enabled: that.permsDto.buttons.pb_spr_pred,
                            run: () => {
                                // kontrola na to jestli případ nemá náhodou nezaúčtované předpisy
                                that.beginOperation({ id: "actGSprPredOp", text: "Kontrola nezaúčtovaných předpisů..." });
                                that.isl.PripadSpravce.maNezaucPredpisy({ ixp: that.Ixp })
                                    .get()
                                    .done((pocet) => {
                                    if (pocet > 0) { // má nezaúčtované předpisy
                                        // zobrazit error dialog
                                        that.isl.PripadSpravce.ziskaniUctarny({ ixp: that.Ixp }).get()
                                            .done((uctarna) => {
                                            that.dialogs.error("Chyba předání správci", `Případ má nezaúčtované pohyby (${pocet}), kontaktujte účtárnu '${uctarna}''.`);
                                        });
                                    }
                                    else { // nemá nezaúčtované předpisy
                                        that.dialogs.confirm("Předání", "Chcete opravdu předat případ jinému správci?")
                                            .on("close", (ev, retVal) => {
                                            if (retVal === "yes") {
                                                that.SprPred();
                                            }
                                        });
                                    }
                                })
                                    .always(() => {
                                    that.endOperation("actGSprPredOp");
                                });
                            }
                        },
                        actGSprVrat: {
                            name: "actGSprVrat",
                            caption: "Vrátit",
                            tooltip: "Vrátit případ",
                            enabled: that.permsDto.buttons.pb_spr_vrat,
                            run: () => {
                                that.dialogs.confirm("Vracení", "Chcete opravdu vrátit případ?")
                                    .on("close", (ev, retVal) => {
                                    if (retVal === "yes") {
                                        that.SprVrat();
                                    }
                                });
                            }
                        },
                        actGSprSchval: {
                            name: "actGSprSchval",
                            caption: "Schválit",
                            tooltip: "Schválit případ pro správce",
                            enabled: that.permsDto.buttons.pb_spr_schval,
                            run: () => {
                                that.beginOperation({ id: "cilSprSchval", text: "Načítání cílového správce převodů..." });
                                that.isl.PripadSpravce.cilovySpravcePrevodu({ ixp: that.Ixp })
                                    .get()
                                    .done((cilovySpravce) => {
                                    var nazev = cilovySpravce.nazev;
                                    that.dialogs.confirm("Schválení", `Chcete opravdu schválit případ pro správce ${nazev}?`)
                                        .on("close", (ev, retVal) => {
                                        if (retVal === "yes") {
                                            that.SprSchval();
                                        }
                                    });
                                })
                                    .always(() => {
                                    that.endOperation("cilSprSchval");
                                });
                            }
                        },
                        actGSprPrij: {
                            name: "actGSprPrij",
                            caption: "Přijmout",
                            tooltip: "Předat případ jinému správci",
                            enabled: that.permsDto.buttons.pb_spr_prij,
                            run: () => {
                                that.beginOperation({ id: "cilSprPrij", text: "Načítání cílového správce převodů..." });
                                that.isl.PripadSpravce.cilovySpravcePrevodu({ ixp: that.Ixp })
                                    .get()
                                    .done((cilovySpravce) => {
                                    var nazev = cilovySpravce.nazev;
                                    that.dialogs.confirm("Schválení", `Chcete opravdu příjmout případ pro správce ${nazev}?`)
                                        .on("close", (ev, retVal) => {
                                        if (retVal === "yes") {
                                            that.SprPrij(cilovySpravce);
                                        }
                                    });
                                })
                                    .always(() => {
                                    that.endOperation("cilSprPrij");
                                });
                            }
                        },
                        actGSprOdmi: {
                            name: "actGSprOdmi",
                            caption: "Odmítnout",
                            tooltip: "Předat případ jinému správci",
                            enabled: that.permsDto.buttons.pb_spr_odmi,
                            run: () => {
                                that.SprOdmi();
                            }
                        }
                    });
                }
