                createSpravaPrip(el) {
                    const that = this;
                    that.gridSpravaPrip = $.newDiv()
                        .appendTo(el)
                        .gautofit({
                        resizersOnTab: false
                    })
                        .ggrid({
                        name: "gridSpravaPrip",
                        multi: false,
                        columnMode: "full",
                        columns: WebClient.Common.GridFormats.SpravaPrip(),
                    });
                }
