                /** Načtení dat z rekapitulace do modelu */
                dataZRekapitulace() {
                    const that = this;
                    $.extend(that.model, this.recapDPH.collectValue([
                        // Osvobozeno
                        { from: { taxType: "-1" /* Gordic.Gin.WebClient.ETaxType.Osvobozeno */, priceType: "baseValue" }, to: "c_d0" },
                        // Bez daně
                        { from: { taxType: "0" /* Gordic.Gin.WebClient.ETaxType.BezDane */, priceType: "baseValue" }, to: "c_z0" },
                        // Základní sazba daně
                        { from: { taxType: "10" /* Gordic.Gin.WebClient.ETaxType.Zakladni */, priceType: "baseValue" }, to: "c_z2" },
                        { from: { taxType: "10" /* Gordic.Gin.WebClient.ETaxType.Zakladni */, priceType: "tax" }, to: "c_d2", },
                        // Snížená sazba daně
                        { from: { taxType: "20" /* Gordic.Gin.WebClient.ETaxType.PrvniSnizena */, priceType: "baseValue" }, to: "c_z1" },
                        { from: { taxType: "20" /* Gordic.Gin.WebClient.ETaxType.PrvniSnizena */, priceType: "tax" }, to: "c_d1", },
                        // Třetí snížená sazba daně
                        // TODO: zatím není podpora
                        //{ from: { taxType: Gordic.Gin.WebClient.ETaxType.DruhaSnizena, priceType: "baseValue" }, to: "c_z3" },
                        //{ from: { taxType: Gordic.Gin.WebClient.ETaxType.DruhaSnizena, priceType: "tax" }, to: "c_d3", },               
                        // Zaokrouhlení
                        { from: { taxType: "-2" /* Gordic.Gin.WebClient.ETaxType.Zaokrouhleno */, priceType: "sum" }, to: "c_zao" },
                        // Celkem
                        { from: { taxType: "-3" /* Gordic.Gin.WebClient.ETaxType.DokladCelkem */, priceType: "sum" }, to: "c_celk" },
                    ]));
                    that.model.c_z0 = Decimal.add(that.model.c_z0, that.model.c_d1); // Do bez daně patří i část osvobozeno
                    var dto = {}; // dto pro rekapitulaci
                    that.recapDPH.findFields().gfield("model", "collect", dto); // Naplnění dto z rekapitulace
                    //that.model.priz_dph = (dto.taxDoc == true ? 10 : 0);                                                            // Daňový doklad
                    //that.model.priz_pdp = (dto.taxedByReciever == true ? 1 : 0);                                                    // Zdanění příjemcem
                    //that.model.mesic_dph = (dto.periodDPH!.month);                                                                  // Měsíc uplatnění DPH
                    //that.model.rok_dph = (dto.periodDPH!.year);                                                                     // Rok uplatnění DPH
                    //that.model.priz_ozp = (dto.otherTaxedPayment ? 1 : 0);                                                          // Ostatní zdanitelné plnění do 10 000 CZK
                    //that.model.priz_pomer = (dto.useDeductionRatio ? 10 : 0);                                                       // Poměr pro odpočet
                }
