                ///**
                // * Metoda pro nastavení komponenty pro zobrazování seznamu adres ESU
                // * @method createpanelEsuAdresy()
                // */
                createpanelEsuAdresy() {
                    var that = this;
                    var modelESU = [];
                    const filter = { ixp: that.Ixp, ixs_esu: that.model.ixs_esu };
                    //filter.ixs_esu = that.model.ixs_esu;
                    let formAdresy = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1", name: "formEsuAdresy" });
                    that.isl.PripadEsuAdresy.list((rq) => {
                        return {
                            filters: filter,
                        };
                    })
                        .getData()
                        .done((data) => {
                        //let formAdresy = new Gordic.Forms.Form({ layoutDescriptor: "L1M1S1", name: "adresyEsuForm" });
                        formAdresy.addSection();
                        if (that.model.ixs_esu == '0000SE00000M') { //TODO: doplnit identifikátor "nulák" pro neurčenou ESU 
                            formAdresy.addRow().addText("Žádné dostupné adresy");
                        }
                        else {
                            for (let i = 0; i < data.length; i++) {
                                let typAdr = data[i].typ_adr;
                                //let adresa = data[i].esu_txt; //-zakomentováno, adresa by se měla dotahovat pomocí ST sloupců (=Řádků obálkové adresy)
                                let adresa = "";
                                let pocRadek = 0;
                                if (data[i].st1 != null) {
                                    adresa += `${data[i].st1} \n`;
                                    pocRadek++;
                                }
                                if (data[i].st2 != null) {
                                    adresa += `${data[i].st2} \n`;
                                    pocRadek++;
                                }
                                if (data[i].st3 != null) {
                                    adresa += `${data[i].st3} \n`;
                                    pocRadek++;
                                }
                                if (data[i].st4 != null) {
                                    adresa += `${data[i].st4} \n`;
                                    pocRadek++;
                                }
                                if (data[i].st5 != null) {
                                    adresa += `${data[i].st5} \n`;
                                    pocRadek++;
                                }
                                if (data[i].st6 != null) {
                                    adresa += `${data[i].st6} \n`;
                                    pocRadek++;
                                }
                                if (data[i].st7 != null) {
                                    adresa += `${data[i].st7} \n`;
                                    pocRadek++;
                                }
                                let nazev = "";
                                switch (typAdr) {
                                    case 0: {
                                        nazev = "Trvalá adresa";
                                        break;
                                    }
                                    case 10: {
                                        nazev = "Doručovací adresa";
                                        break;
                                    }
                                    case 20: {
                                        nazev = "Zaměstnavatel (adresa)";
                                        break;
                                    }
                                    case 30: {
                                        nazev = "Kontaktní adresa";
                                        break;
                                    }
                                    default: {
                                        nazev: "Jiná adresa";
                                        break;
                                    }
                                }
                                formAdresy.addRow(nazev);
                                //formAdresy.addField("gstringbox", { name: `adr${i}`, defaultValue: adresa, validators: [] });
                                formAdresy.addField("gstringbox", {
                                    name: `adr${i}`,
                                    defaultValue: adresa,
                                    rows: pocRadek,
                                    disabled: true,
                                });
                            }
                            //TODO: v tomto bodě se zamyslet, jak to má fungovat a zda je to vůbec potřeba...
                            if (formAdresy.form.sections == null || formAdresy.form.sections.length == 0 || formAdresy.form.sections[0].rows == null || formAdresy.form.sections[0].rows.length == 0) {
                                formAdresy.addRow().addText("Žádné dostupné adresy");
                            }
                        }
                        var finalForm = $.newDiv("panelEsuAdresyFormDiv")
                            .gform("createFrom", formAdresy);
                        that.element.gsidebar("getPanel", "panelEsuAdresy").empty();
                        that.element.gsidebar("getPanel", "panelEsuAdresy").append(finalForm);
                        //// získání políček v sidePanelu
                        //var fieldsESU: JQuery<HTMLElement> = that.element.gsidebar("getPanel", "sidePanelESU").find('[name="basePanelItem_0"]');
                        //// Nastavení CSS defaultního vybraného ESU
                        //$(fieldsESU[0]).find(".g-kpi-multirow-body-primaryText").addClass("important-value");
                    });
                }
