                /**
                 *
                 * @returns true / false
                 */
                jsteZpracovatel() {
                    const that = this;
                    that.endOperation(); // konec operace pro jistotu kdyby náhodou byla funkce někde použita a zapomnělo se na to.
                    //if (ixsFunAct == null || ixsFunAct == undefined) {
                    //    return that.dialogs.error("Chyba", "ID zpracovatele nebylo nalezeno.");
                    //}
                    if (that.model.ixs_fun_akt != that.IxsFun) {
                        that.dialogs.error("Chyba", "Nejste zpracovatelem dokumentu.");
                        return false;
                    }
                    else {
                        return true;
                    }
                }
                /**
                 * Metoda konrolující zda se jedná o případ Vlastní
                 * this.model.ixs_fun_akt == that.IxsFun
                 */
                JeVlastni() {
                    const that = this;
                    return (that.model.ixs_fun_akt == that.IxsFun); //TODO: && this.model.ixs_su_akt == that.IxsSu); //TODO: Zjistit KDE VZÍT SPIS. UZEL 
                }
                /** Metoda konrolující zda se jedná o případ Evidovaný */
                JeEvidovany() {
                    return (this.model.dat_evid != null && this.model.ac != null);
                }
                /** Metoda konrolující zda se jedná o případ Podaný */
                JePodany() {
                    return (!this.JeEvidovany());
                }
