                testVyrovnanostiOpravnychPolozekPriPredani() {
                    const that = this;
                    var def = $.Deferred();
                    //test na opr. položky případu
                    var l_odepsat_c_opr = new Decimal(0);
                    that.isl.Pripad.testVyrovnanostiOpravnychPolozekPriPredani({ ixpDdp: that.Ixp }).get()
                        .done((data) => {
                        if (data) {
                            let d_opr_zvys = new Decimal(data.castka1);
                            let d_opr_sniz = new Decimal(data.castka2);
                            if (!d_opr_zvys.equals(d_opr_sniz)) { // if (d_opr_zvys != d_opr_sniz) {
                                that.dialogs.confirm("Upozornění", "Případ má nevyrovnané opravné položky, předáním budou tyto opravné položky vyrovnány. \n\n Chcete pokračovat v převodu?")
                                    .on("close", (ev, ret) => {
                                    if (ret = "yes") {
                                        l_odepsat_c_opr = d_opr_zvys.minus(d_opr_sniz);
                                        def.resolve(l_odepsat_c_opr);
                                    }
                                    else {
                                        def.reject();
                                    }
                                });
                            }
                            else {
                                //l_odepsat_c_opr = 0;
                                def.resolve(l_odepsat_c_opr);
                            }
                        }
                        else {
                            that.dialogs.error("Chyba", "Nastala chyba při testu vyrovnanosti opravných položek předání")
                                .on("close", () => {
                                def.reject();
                            });
                        }
                    })
                        .fail(function (jqXHR, typ, obj) {
                        that.endOperation();
                        if (typ === "exception") {
                            obj.handled = true;
                            that.dialogs.error("Chyba", obj.baseMessage)
                                .on("close", (ev, retVal) => {
                                def.reject();
                            });
                        }
                        else {
                            def.reject();
                        }
                    });
                    return def.promise();
                }
