                // TODO: možná bude potřeba upravit throwy - nevím zda chci vyhazovat zbytečné errory jen proto že se uživatel rozhodl nepokračovat
                async zpracujVysledek(retData, zpusob_vyr) {
                    const that = this;
                    if (retData?.text1?.length > 0) {
                        await WebClient.Common.Base.errorAsync(that, "Chyba", retData.text1);
                        throw new Error("Ukončeno chybou");
                    }
                    if (retData?.text2?.length > 0) {
                        const ok = await WebClient.Common.Base.confirmAsync(that, "Upozornění", retData.text2);
                        if (!ok) {
                            throw new Error("Uživatel odmítl pokračovat");
                        }
                    }
                    if (retData?.text3?.length > 0) {
                        const ok = await WebClient.Common.Base.confirmAsync(that, "Upozornění", retData.text3);
                        if (!ok) {
                            throw new Error("Uživatel odmítl pokračovat");
                        }
                    }
                    const finalOk = await WebClient.Common.Base.confirmAsync(that, "Upozornění", retData.text4);
                    if (!finalOk) {
                        throw new Error("Uživatel odmítl finální potvrzení");
                    }
                    await this.vyrizeniPoplatnikaAsync(zpusob_vyr);
                }
