                /**
                 * Rozdělí string podle odentrování na pole, přičemž zajistí,
                 * aby každé pole mělo maximálně 254 znaků,
                 * a nerozdělilo string uprostřed slova.
                 * @param input Vstupní string, který se má rozdělit..
                 * @returns Pole stringů rozdělených podle odsazení a délky.
                 */
                splitByIndentationAndLength(input) {
                    const maxLength = 254;
                    const lines = input.split(/\r?\n/);
                    const result = [];
                    for (let line of lines) {
                        line = line.trim();
                        while (line.length > maxLength) {
                            let splitIndex = maxLength;
                            //  Zajistí, aby nedošlo k rozdělení uprostřed slova.
                            if (line[maxLength] !== ' ' && line[maxLength - 1] !== ' ') {
                                splitIndex = line.lastIndexOf(' ', maxLength);
                                if (splitIndex === -1) {
                                    splitIndex = maxLength; // Pokud nenalezne mezeru, rozdělí podle maxLength
                                }
                            }
                            result.push(line.substring(0, splitIndex).trim());
                            line = line.substring(splitIndex).trim();
                        }
                        if (line.length > 0) {
                            result.push(line);
                        }
                    }
                    return result;
                }
                /**
                 * Slouží pro ostestování odřádkování stringu
                 */
