                /**
                 * Sets the age based on the date of birth.
                 * @param dateOfBirth The date of birth.
                 * @returns The calculated age.
                 */
                nastavVekPodleDataNarozeni(dateOfBirth) {
                    //TODO: možná bude potřeba nastavovat věk také s ohledem na datum úmrtí/ukončení
                    if (dateOfBirth == null || dateOfBirth == undefined) {
                        return 0;
                    }
                    const today = new Date();
                    let age = today.getFullYear() - dateOfBirth.getFullYear();
                    const monthDifference = today.getMonth() - dateOfBirth.getMonth();
                    // If the current month is before the birth month or it's the birth month but the current day is before the birth day, subtract one year from the age
                    if (monthDifference < 0 || (monthDifference === 0 && today.getDate() < dateOfBirth.getDate())) {
                        age--;
                    }
                    return age;
                }
                nastavPoleVeku() {
                    const that = this;
                    //var form = that.element.findForms("formZakladniInfo");
                    var form = that.element.findForms();
                    //var d = form.findFields("dat_nar").gfield("getValue");
                    //TODO: kvůli problému se ziskáním data z políčka, načítám datum pouze z modelu (zatím)
                    //TODO: bude potřeba vyřešit (při změně esu se dle mého věk nezmění)
                    var dat_nar = that.model.ExterniSubjekt?.dat_nar;
                    //!var dat_umrti = that.model.ExterniSubjekt?.dat_umrti;
                    var dn = parseDate(dat_nar);
                    //!var du = parseDate(dat_umrti!);
                    //var d = form.findFields("ExterniSubjekt\.dat_nar").gfield("getValue");
                    //var d: JsonDate | null | undefined = that.model.ExterniSubjekt?.dat_nar;
                    if (dn != null || dn != undefined) {
                        var vek = this.nastavVekPodleDataNarozeni(dn);
                        form.findFields("vekEsu").gfield("setValue", vek, { initialValues: that.inicializaceDetailu });
                    }
                }
                /**
                 * Checks if the given input is of Date type.
                 * @param input The input to check.
                 * @returns True if the input is a Date object, false otherwise.
                 */
                isDateType(input) {
                    return input instanceof Date && !isNaN(input.getTime());
                }
                /**
                 * Formats a date to the dd.MM.yyyy format.
                 * @param date The date to format.
                 * @returns The formatted date string.
                 */
                formattDate(date) {
                    if (!this.isDateType(date)) {
                        return "";
                    }
                    const day = date.getDate() ?? "";
                    const month = date.getMonth() + 1; // Months are zero-based
                    const year = date.getFullYear() ?? "";
                    const dayString = day < 10 ? '0' + day : day.toString();
                    const monthString = month < 10 ? '0' + month : month.toString();
                    return `${dayString}.${monthString}.${year}`; // Outputs: dd.MM.yyyy
                }
                priznakSmrti(dat, priz) {
                    const that = this;
                    var label = "";
                    var tooltip = "";
                    var dat_umrti = dat ?? that.model.ExterniSubjekt.dat_umrti;
                    var priz_umrti = priz ?? that.model.ExterniSubjekt.priz_umrti;
                    var dat_string = "";
                    if (priz_umrti == 1 && dat_umrti != null) {
                        dat_string = that.formattDate(parseDate(dat_umrti));
                    }
                    if (that.model.ExterniSubjekt.typ_esu == 20) {
                        if (priz_umrti == 1) {
                            label = `Příznak úmrtí (†${dat_string})`; // "Příznak ukončení: " 
                            tooltip = `Poplatník zemřel: ${dat_string}`; // "Datum ukončení: "
                        }
                        else {
                            label = "Příznak úmrtí"; // "Příznak ukončení: " 
                            tooltip = "Poplatník nezemřel: "; // "Datum ukončení: "
                        }
                    }
                    else {
                        if (priz_umrti == 1) {
                            label = `Příznak ukončení (${dat_string})`; // "Příznak ukončení: " 
                            tooltip = `Datum ukončení činnosti: ${dat_string}`; // "Datum ukončení: "
                        }
                        else {
                            label = "Příznak ukončení "; // "Příznak ukončení: " 
                            tooltip = "Neukončeno: "; // "Datum ukončení: "
                        }
                    }
                    return [label, tooltip];
                }
