                setActiveOperationAndReloadData(withoutReload = false) {
                    const that = this;
                    // vyvolání trigger o aktivní operaci
                    that.trigger(WebClient.DdpDetail.triggerChange, [{ data: that.model }]);
                    // aktualizace detailu
                    if (!withoutReload) {
                        //that.element.trigger("rememberinitialopen");
                        //return that.load();
                        return that.reloadData();
                    }
                    else
                        return $.Deferred().resolve().promise();
                }
